        _impartial(dependant.call)
    ) or inspect.isgeneratorfunction(_unwrapped_call(dependant.call)):
        return True
    dunder_call = getattr(_impartial(dependant.call), "__call__", None)
    if dunder_call is None:
        return False
    if inspect.isgeneratorfunction(
        _impartial(dunder_call)
    ) or inspect.isgeneratorfunction(_unwrapped_call(dunder_call)):
        return True
    return False

def _unwrapped_call(call):
    if call is None:
        return call
    return inspect.unwrap(_impartial(call))

def _impartial(func):
    from functools import partial
    while isinstance(func, partial):
        func = func.func
    return func

class MyClass:
    def __call__(self):
        yield 1

